(async () => {
  const E = window.__echoes;
  const sleep = (ms) => new Promise(r => setTimeout(r, ms));
  const log = [];
  E.cmd('startRun');
  await sleep(120);
  let guard = 0;
  while (guard++ < 400) {
    const v = E.cmd('runState');
    if (v.phase === 'victory' || v.phase === 'defeat') { log.push({act:'end', phase:v.phase, room:v.room}); break; }
    if (v.phase === 'combat') {
      if (v.room === 8) {
        E.cmd('killAllEnemies');
        E.cmd('killBoss');
        log.push({act:'bosskill', room:v.room, tick:E.tick});
      } else {
        E.cmd('clearRoom');
        log.push({act:'clear', room:v.room, mode:v.mode, tick:E.tick});
      }
    } else if (v.phase === 'reward') {
      log.push({act:'reward', room:v.room, promised:v.reward&&v.reward.promised, type:v.reward&&v.reward.type, id:v.reward&&v.reward.id, sub:v.reward&&v.reward.substituted, line:v.reward&&v.reward.line, free:v.freeSkillSlots});
      E.cmd('draftTake');
    } else if (v.phase === 'path') {
      log.push({act:'path', room:v.room, next:v.path.nextRoom, opts:v.path.options.map(o=>o.win+':'+o.reward), free:v.path.freeSkillSlots});
      E.cmd('pathChoose', 0);
    } else if (v.phase === 'shop') {
      log.push({act:'shop', room:v.room, wallet:v.wallet, stock:v.shop.stock.map(s=>s.node+'/'+s.rarity+'/'+s.price+'/aff'+s.affordable)});
      E.cmd('shopAdvance');
    }
    await sleep(120);
  }
  const ev = E.events.filter(e => ['run_start','room_enter','room_cleared','reward_offer','draft_taken','path_offer','path_chosen','room_transition','shop_open','shop_close','run_end','glint_gain'].includes(e.type)).map(e=>({t:e.tick, ty:e.type, i:e.index, m:e.mode, r:e.reward, room:e.room, next:e.nextRoom, res:e.result, w:e.wallet, from:e.from, to:e.to}));
  return { log, tail: ev.slice(-40), state: E.cmd('runState') };
})()
